ax_handles  = gobjects(n_cond2plot, n_sens);

for sens_idx = 1:n_sens
    sensor = sensor_labels{sens_idx};
   
    % Global axis limits
    %-------------------
    d1        = cellfun(@(x) mean(x.avg(:,timewin2plot(1):timewin2plot(2)),2) , fmodels_gavg(idx4model, cond_idxs, sens_idx), 'UniformOutput', false);
    ylim_min  = min(vertcat(d1{:}),[],"all"); 
    ylim_max  = max(vertcat(d1{:}),[],"all");
    limit_val = max(abs([ylim_min, ylim_max]));
    
    for con_idx2 = 1:n_cond2plot
        condition = conditions2plot{con_idx2};
        con_idx   = cond_idxs(con_idx2);
        
        plot_idx = (con_idx2 - 1) * n_sens + sens_idx;  
        ax_handles(con_idx2, sens_idx) = subplot(n_cond2plot ,n_sens, plot_idx); % Capture axes handle

        % Select layout
        switch sensor
            case 'MEG'
                layout = layout_meg;
            case 'EEG'
                % fix it
                layout = layouts_eeg{1,1};
            case 'ear-EEG'
                %layout = layouts_ear_eeg{sub_idx,con_idx};
                layout = layout_ear_eeg_generic;
            otherwise
                error('Unexpected sensor (%s)!',sensor)
        end

        cfg             = [];
        cfg.xlim        = [time_vec(timewin2plot(1)),time_vec(timewin2plot(2))];
        cfg.zlim        = [-limit_val, limit_val];
        cfg.comment     = 'no';
        cfg.layout      = layout;
        cfg.interactive = 'no';
        cfg.figure      = gca; %ax_handles(sens_idx, con_idx); 
        cfg.colorbar    = 'no'; % Turn off individual colorbars
        ft_topoplotER(cfg, fmodels_gavg{idx4model, con_idx, sens_idx});
        colormap(bluewhitered)

        % Add modified labels for conditions and sensors
        %-----------------------------------------------
        if sens_idx == 1
            text('Units', 'normalized', ...
                 'Position', [-0.15, 0.5], ... % X, Y position relative to the axes
                 'String', condition, ...
                 'Rotation', 90, ...
                 'HorizontalAlignment', 'center', ...
                 'VerticalAlignment', 'bottom', ...
                 'FontWeight', 'bold', ...
                 'Interpreter', 'none', ...
                 'FontSize',15);
        end

        if con_idx2 == 1
            title(sensor_labels{sens_idx}, 'FontSize', 15)
        end

    end % Loop over conditions

    % Add a single colorbar for the entire row
    %-----------------------------------------
    first_ax_pos = get(ax_handles(1, sens_idx), 'Position');
    last_ax_pos  = get(ax_handles(n_cond2plot, sens_idx), 'Position');

    % Calculate full width (from start of first plot to end of last plot)
    full_width = (last_ax_pos(1) + last_ax_pos(3)) - first_ax_pos(1);
    
    % Define position: [left, bottom, width, height]
    % We place it below 'last_ax_pos(2)' by subtracting a small offset
    cb_pos = [first_ax_pos(1), ...           
              last_ax_pos(2) - 0.02, ...     
              full_width, ...                
              0.025];                        
    
    % Create the axes and the horizontal colorbar
    cb_ax = axes('Position', cb_pos);
    cb    = colorbar(cb_ax, 'Location', 'southoutside', 'Orientation', 'horizontal'); 
    
