%% Functions
%--------------------------------------------------------------------------

function output_struct = normalize_avg_field(input_struct)
    % Start with a copy of the original struct
    output_struct = input_struct;
    
    % Get the data and normalization factor
    avg_data    = input_struct.avg;
    norm_factor = max(abs(avg_data(:)));
    
    % Update the field, avoiding division by zero
    if norm_factor > 0
        output_struct.avg = avg_data / norm_factor;
    end
end
